/// One of the orders: its detail, a form per action, each when the caller may.
/// A refused action renders its form again as sent, with its errors.
#[component]
async fn orders_item(
    cx: &Cx,
    order_id: String,
    #[default] add_line_form: Option<(OrderAddLineArgsForm, FormErrors)>,
) -> topcoat::Result<impl View> {
    let href = orders_item_href(&order_id).unwrap_or_else(|| PREFIX.to_owned());
    let found = call_order_get_order(cx, &order_id)
        .await
        .map(|item| {
            let record = OrderRecord::from(item);
            (title_or(&record.number, "Order"), record)
        })
        .map_err(Refusal::clone);
    let choices = choices_of(cx, "orders");
    let labels = match &found {
        Ok((_, record)) => references::order_labels(cx, std::slice::from_ref(record), choices.clone()).await,
        Err(_) => choices.clone(),
    };
    let add_line_form = match add_line_form {
        Some(sent) => Some(sent),
        None => operations::can_order_add_line(cx).await.is_ok().then(|| (OrderAddLineArgsForm::new(order_id.as_str()), FormErrors::default())),
    };
    let add_line_form_choices = match &add_line_form {
        Some((form, _)) => references::order_add_line_args_form_choices(cx, form, choices.clone()).await,
        None => choices.clone(),
    };
    Ok(view! {
        match found {
            Err(refusal) => refused(refusal: refusal, next: href),
            Ok((heading, record)) => {
                <h1>(heading)</h1>
                order_detail(record: record, choices: labels)
                if let Some((form, errors)) = add_line_form {
                    <form method="post" action=(format!("{href}/add-line")) class="ss-action" data-action="add-line">
                        order_add_line_args_fields(form: form, errors: errors, choices: add_line_form_choices)
                        <button type="submit">"Add line"</button>
                    </form>
                }
            },
        }
    })
}

