/// One of the products: its detail, the sections under it, each when the caller
/// may.
#[component]
async fn products_item(
    cx: &Cx,
    product_id: String,
) -> topcoat::Result<impl View> {
    let href = products_item_href(&product_id).unwrap_or_else(|| PREFIX.to_owned());
    let found = call_product_get_product(cx, &product_id)
        .await
        .map(|item| {
            let record = ProductRecord::from(item);
            (title_or(&record.name, "Product"), record)
        })
        .map_err(Refusal::clone);
    let choices = choices_of(cx, "products");
    let labels = match &found {
        Ok((_, record)) => references::product_labels(cx, std::slice::from_ref(record), choices.clone()).await,
        Err(_) => choices.clone(),
    };
    Ok(view! {
        match found {
            Err(refusal) => refused(refusal: refusal, next: href),
            Ok((heading, record)) => {
                <h1>(heading)</h1>
                product_detail(record: record, choices: labels)
                products_reviews_section(product_id: product_id.clone())
            },
        }
    })
}

